// The worker project's typecheck, behind a guard that names what is missing.
//
// `web/src/local/wasm/` is GENERATED by `npm run build:wasm` and gitignored, so
// on a fresh checkout — and in the `web-client` CI job, which has no Rust
// toolchain and builds no module — the worker project's inputs are not there.
// Without this guard that reads as a resolution error about a file nobody
// committed; with it, it reads as one sentence naming the command to run.
//
// `YOKOHAMA_WASM_OPTIONAL=1` turns the refusal back into a skip that SAYS it
// checked nothing — the same shape as `YOKOHAMA_WEB_E2E_OPTIONAL` and the BGA
// corpus opt-out, and for the same reason: a silent skip is a green check that
// means nothing.
import { spawnSync } from "node:child_process";
import { existsSync } from "node:fs";
import { fileURLToPath } from "node:url";

const web = fileURLToPath(new URL("..", import.meta.url));
const glue = fileURLToPath(new URL("../src/local/wasm/yokohama_wasm.d.ts", import.meta.url));

if (!existsSync(glue)) {
  if (process.env.YOKOHAMA_WASM_OPTIONAL === "1") {
    console.log(
      "typecheck: the worker project was SKIPPED and checked NOTHING — " +
        "src/local/wasm/yokohama_wasm.d.ts is absent and YOKOHAMA_WASM_OPTIONAL=1.",
    );
    process.exit(0);
  }
  console.error(
    "typecheck: the worker project cannot be checked — " +
      "src/local/wasm/yokohama_wasm.d.ts is absent.\n" +
      "  Run `npm run build:wasm` (it needs the Rust toolchain, the " +
      "wasm32-unknown-unknown target and wasm-bindgen 0.2.128).\n" +
      "  Set YOKOHAMA_WASM_OPTIONAL=1 to skip it and check nothing.",
  );
  process.exit(1);
}

const tsc = spawnSync(
  process.platform === "win32" ? "npx.cmd" : "npx",
  ["tsc", "-p", "tsconfig.worker.json", "--noEmit"],
  { cwd: web, stdio: "inherit" },
);
process.exit(tsc.status ?? 1);
